"""Apply docs/DESIGN.md to results/raw_*.csv. Writes results/summary.csv, RESULTS_TABLES.md, verdict.md, figures/r3.png."""
import sys, pathlib; sys.path.insert(0, str(pathlib.Path(__file__).resolve().parents[1]))
import glob, pandas as pd, numpy as np, matplotlib; matplotlib.use("Agg"); import matplotlib.pyplot as plt
from scipy.stats import spearmanr
import config as C
d = pd.concat([pd.read_csv(f) for f in sorted(glob.glob(str(C.RES / "raw_*.csv")))], ignore_index=True); d["passed"] = d.passed.astype(bool)
d["variant"] = np.where(d.tech == "fp", d.method + " fp", d.method + " " + d.rounding); d["fresh"] = [s in C.FRESH[a] for a, s in zip(d.arch, d.seed)]; d["repl"] = [s in C.REPLICATION.get(a, []) for a, s in zip(d.arch, d.seed)]
q = d[(d.tech != "fp") & (d.fresh | d.repl)].copy(); q["moved"] = q.changed >= C.STUCK_BELOW
def allp(s): n = len(s); return bool(s.sum() >= (n // 2 + 1 if n > 2 else n))
cell = q.groupby(["arch", "tech", "bits", "variant", "fresh"]).agg(seeds=("seed", "nunique"), passed=("passed", allp), score=("forget_score", "median"), retain=("retain_ratio", "median"), steps=("steps", "median"), seconds=("seconds", "median"), moved=("moved", allp)).reset_index()
cell.to_csv(C.RES / "summary.csv", index=False)
F = d[(d.tech == "fp") & (d.fresh | d.repl)].groupby(["arch", "variant", "fresh"]).agg(seeds=("seed", "nunique"), passed=("passed", allp), score=("forget_score", "median"), retain=("retain_ratio", "median"), steps=("steps", "median")).reset_index()
VARS = ["TPU stochastic", "TPU nearest", "MaxLoss stochastic", "MaxLoss nearest"]
md = ["# Results tables (generated by steps/05_report.py; rules in docs/DESIGN.md)\n", "A cell passes when all fresh seeds pass the strict rule (forget score 0.8-1.2, retain ratio <= 1.10). The gate uses fresh seeds only.\n", "## Full-precision reference\n", F.assign(score=F.score.round(2), retain=F.retain.round(2)).to_markdown(index=False)]
cf = cell[cell.fresh]
for arch in C.ARCHS:
    A = cf[cf.arch == arch]
    if A.empty: continue
    t = A.pivot_table(index=["tech", "bits"], columns="variant", values="passed", aggfunc="first").reindex(columns=VARS)
    md += [f"\n## {arch}: strict pass per cell (fresh seeds)\n", t.map(lambda x: "" if pd.isna(x) else ("pass" if x else "-")).reset_index().to_markdown(index=False)]
    S = A[A.variant == "TPU stochastic"].assign(v=lambda x: x.score.round(2).astype(str) + " / " + x.retain.round(2).astype(str) + " / " + x.steps.astype(int).astype(str)).pivot_table(index="tech", columns="bits", values="v", aggfunc="first")
    md += [f"\nTPU + stochastic rounding, {arch}: median forget score / retain ratio / steps\n", S[sorted(S.columns, reverse=True)].to_markdown()]
# stop reasons, reference-free check
Qs = q[(q.rounding == "stochastic") & q.fresh]
Qs = Qs.assign(why=np.where(Qs.steps >= np.where(Qs.method == "TPU", C.TPU_CFG["steps"], C.STEPS), "ran out of steps", np.where(Qs.s_hat >= 0.95, "target reached", "retain guard")))
md += ["\n## How the stochastic runs ended (all seeds, all cells)\n", Qs.groupby(["method", "why"]).size().unstack(fill_value=0).to_markdown()]
Q2 = Qs[Qs.method == "TPU"]; pred = (Q2.s_hat >= 0.8) & (Q2.s_hat <= 1.2) & (Q2.retain_est <= 1.10)
md += [f"\n## Reference-free check, TPU stochastic runs ({len(Q2)}): predicted-pass vs judged-pass agree in {int((pred == Q2.passed).sum())} runs; both pass {int((pred & Q2.passed).sum())}; judged pass {int(Q2.passed.sum())}; predicted pass {int(pred.sum())}."]
open(C.RES / "RESULTS_TABLES.md", "w").write("\n".join(md))

# ---- per-run view (POST-HOC, not the gate): each seed counted separately ----
R = d[d.fresh & (d.tech != "fp") & d.bits.isin([8, 6, 4])]
pr = R.groupby(["arch", "variant"]).agg(runs=("passed", "size"), strict_pass=("passed", "sum"), median_score=("forget_score", "median"), median_retain=("retain_ratio", "median"), median_steps=("steps", "median")).round(2).reset_index()
md += ["\n## POST-HOC per-run view (each fresh seed counted separately, quantized runs INT8/6/4, all quantizers)\n", pr.to_markdown(index=False)]
pf = d[d.fresh & (d.tech == "fp")][["arch", "seed", "variant", "forget_score", "retain_ratio", "passed", "steps"]].round(2)
md += ["\n## Full precision per seed\n", pf.to_markdown(index=False)]
open(C.RES / "RESULTS_TABLES.md", "w").write("\n".join(md))
# ---- verdict ----
G = lambda var, bits=(8, 6, 4), arch=None: cf[(cf.variant == var) & cf.bits.isin(bits) & ((cf.arch == arch) if arch else True)]
fpf = F[F.fresh & (F.variant == "TPU fp")].set_index("arch").passed
L = ["# Verdict (rules from docs/DESIGN.md, applied as written, fresh seeds)\n", "## G1: TPU works in full precision\n"] + [f"- {a}: {'pass' if a in fpf.index and fpf[a] else ('FAIL' if a in fpf.index else 'no result')}" for a in C.ARCHS]
g1 = all(a in fpf.index and fpf[a] for a in C.ARCHS)
n_s = {a: int(G("TPU stochastic", arch=a).passed.sum()) for a in C.ARCHS}; n_cells = {a: len(G("TPU stochastic", arch=a)) for a in C.ARCHS}; tot = sum(n_s.values())
g2 = tot >= 18 and all(n_s[a] >= 5 for a in C.ARCHS) and all(n_cells[a] == 9 for a in C.ARCHS)
L += ["", f"**G1 {'HOLDS' if g1 else 'DOES NOT HOLD'}**", "", "## G2: TPU + stochastic rounding on quantized models\n"] + [f"- {a}: {n_s[a]} of {n_cells[a]} cells pass (need >=5 of 9)" for a in C.ARCHS] + [f"- total {tot} of {sum(n_cells.values())} (need >=18 of 27)", "", f"**G2 {'HOLDS' if g2 else 'DOES NOT HOLD'}**"]
n_n = int(G("TPU nearest", bits=(6, 4)).passed.sum()); g3 = n_n <= 4
L += ["", "## G3: nearest rounding as control", f"- TPU + nearest rounding passes in {n_n} of {len(G('TPU nearest', bits=(6, 4)))} cells at INT6/INT4 (need <=4)", "", f"**G3 {'HOLDS' if g3 else 'DOES NOT HOLD'}**"]
n_m = int(G("MaxLoss stochastic").passed.sum()); g4 = tot > n_m
L += ["", "## G4: against the best existing method", f"- TPU stochastic {tot} cells vs MaxLoss stochastic {n_m} cells", "", f"**G4 {'HOLDS' if g4 else 'DOES NOT HOLD'}**", "", f"## Verdict: **{'ESTABLISHED' if g1 and g2 and g3 and g4 else 'PARTLY ESTABLISHED' if g1 and g2 else 'NOT ESTABLISHED'}**"]
fails = G("TPU stochastic")[~G("TPU stochastic").passed]; L += ["", "Cells where TPU + stochastic did not pass: " + ("; ".join(f"{r.arch} {r.tech} INT{r.bits} (score {r.score:.2f}, retain {r.retain:.2f}, {int(r.steps)} steps)" for r in fails.itertuples()) or "none")]
open(C.RES / "verdict.md", "w").write("\n".join(L)); print("\n".join(L))
# ---- figure ----
fig, ax = plt.subplots(1, 3, figsize=(13, 3.8), sharey=True)
for a_, arch in zip(ax, C.ARCHS):
    A = cf[cf.arch == arch]
    for i, (v, col) in enumerate(zip(VARS, ["#e8710a", "#c4c7cc", "#1a73e8", "#9ab7f0"])):
        y = [int(A[(A.variant == v) & (A.bits == b)].passed.sum()) for b in (8, 6, 4)]; a_.bar(np.arange(3) + (i - 1.5) * 0.2, y, 0.2, color=col, label=v)
    a_.set_xticks(range(3)); a_.set_xticklabels(["INT8", "INT6", "INT4"]); a_.set_ylim(0, 3.3); a_.set_title(f"{arch}: cells that forgot correctly (of 3 quantizers)", fontsize=9)
ax[0].legend(frameon=False, fontsize=7); plt.tight_layout(); plt.savefig(C.FIG / "r3.png", dpi=150)

# ---- addendum: replication on the extra PatchTST seed (docs/ADDENDUM.md) ----
Rp = d[d.repl & (d.arch == "patchtst")]
if len(Rp):
    qq = Rp[Rp.tech != "fp"]; cnt = lambda v: qq[(qq.method + " " + qq.rounding) == v]
    t, m_, n_ = cnt("TPU stochastic"), cnt("MaxLoss stochastic"), cnt("TPU nearest")
    fpR = Rp[(Rp.tech == "fp") & (Rp.method == "TPU")]
    r1 = bool(fpR.passed.all()); r2 = int(t.passed.sum()); r3 = int(m_.passed.sum())
    verdict = "CONFIRMED" if r1 and r2 >= 6 and r3 <= 2 else "PARTLY CONFIRMED" if (r1 and r2 >= 6) or (r1 and 4 <= r2 <= 5) else "NOT CONFIRMED"
    both = d[(d.arch == "patchtst") & (d.fresh | d.repl) & (d.tech != "fp") & (d.method == "TPU") & (d.rounding == "stochastic") & d.bits.isin([8, 6, 4])].groupby(["tech", "bits"]).passed.all()
    L2 = ["# Replication on PatchTST seed 3 (rules in docs/ADDENDUM.md)\n", f"- R1 TPU in full precision passes: {'yes' if r1 else 'NO'} (score {fpR.forget_score.iloc[0]:.2f}, retain {fpR.retain_ratio.iloc[0]:.2f})",
          f"- R2 TPU + stochastic passes {r2} of {len(t)} cells (need >= 6)", f"- R3 MaxLoss + stochastic passes {r3} of {len(m_)} cells (need <= 2)", f"- TPU + nearest passes {int(n_.passed.sum())} of {len(n_)} cells", "", f"**Replication: {verdict}**", "",
          "TPU + stochastic by bit width (extra seed): " + ", ".join(f"INT{b} {int(t[t.bits == b].passed.sum())}/{int((t.bits == b).sum())}" for b in (8, 6, 4)),
          f"With both PatchTST seeds (2 and 3), a cell passes only if both pass: {int(both.sum())} of {len(both)} cells.", "", "Per cell (extra seed), TPU + stochastic: forget score / retain ratio / steps", "",
          t.assign(v=lambda x: x.forget_score.round(2).astype(str) + " / " + x.retain_ratio.round(2).astype(str) + " / " + x.steps.astype(int).astype(str)).pivot_table(index="tech", columns="bits", values="v", aggfunc="first")[[8, 6, 4]].to_markdown()]
    open(C.RES / "replication.md", "w").write("\n".join(L2)); print("\n".join(L2))
